<section class="slide" data-title="Try It Yourself">
  <p class="lead">Exercises with the tutorial code</p>
  <div class="content">
    <ul class="lec">
      <li><b>Human data</b> : collect 50, then 100 demos — does the Diffusion vs MLP-BC gap grow?</li>
      <li><b>No goal frame</b> : train in world coordinates — how much success is lost?</li>
      <li><b>Chunks</b> : vary the prediction / execution horizons (1, 4, 8, 16)</li>
      <li><b>History</b> : one observation frame — which mistakes appear without velocity?</li>
      <li><b>DAgger</b> : record your corrections in the viewer and retrain</li>
      <li><b>Robustness</b> : evaluate with friction 0.2 instead of 0.4 — think domain randomization</li>
      <li><b>RL</b> : put the 0.15 m / 10° test into the reward — does BC+PPO pass the expert?</li>
    </ul>
  </div>
</section>

</div></div>

<div id="hud"><b id="hud-n">1</b> / <span id="hud-t">22</span></div>
<div id="help">← → navigate · O overview · F fullscreen · Ctrl+P print (PDF)</div>

<script>
(function(){
  var deck   = document.getElementById('deck');
  var slides = Array.prototype.slice.call(deck.querySelectorAll('.slide'));
  var idx = 0;

  // ---- inject slide chrome (title bar · mark · footer · number) ------------
  var CREDIT = 'Sookmyung Women’s Univ. Autonomous Mechanical Systems Lab';
  slides.forEach(function(s, i){
    if (s.classList.contains('cover')) return;
    var bar = document.createElement('div'); bar.className = 'bar';
    var h2  = document.createElement('h2');  h2.textContent = s.dataset.title || '';
    var mk  = document.createElement('img'); mk.className = 'mark'; mk.alt = '';
    mk.src  = 'assets/logo/smwu-logo-mark-mono.png';
    s.insertBefore(mk, s.firstChild);
    s.insertBefore(h2, s.firstChild);
    s.insertBefore(bar, s.firstChild);
    var f  = document.createElement('div'); f.className  = 'foot';
    var nb = document.createElement('div'); nb.className = 'foot-num-band';
    var cr = document.createElement('div'); cr.className = 'foot-credit'; cr.textContent = CREDIT;
    var nu = document.createElement('div'); nu.className = 'foot-num';    nu.textContent = String(i + 1);
    s.appendChild(f); s.appendChild(nb); s.appendChild(cr); s.appendChild(nu);
  });
  document.getElementById('hud-t').textContent = String(slides.length);

  // ---- math -----------------------------------------------------------------
  function renderMath(){
    if (!window.renderMathInElement) return false;
    renderMathInElement(deck, {
      delimiters: [{left:'\\[', right:'\\]', display:true}, {left:'\\(', right:'\\)', display:false}],
      throwOnError: false
    });
    document.body.setAttribute('data-math', 'done');
    return true;
  }
  window.addEventListener('DOMContentLoaded', renderMath);

  // ---- fit to viewport --------------------------------------------------------
  function fit(){
    if (document.body.classList.contains('overview')) { deck.style.transform = 'none'; return; }
    var s = Math.min(window.innerWidth / 1280, window.innerHeight / 720);
    deck.style.transform = 'scale(' + s + ')';
  }
  function show(n){
    idx = Math.max(0, Math.min(slides.length - 1, n));
    slides.forEach(function(s, i){ s.classList.toggle('is-active', i === idx); });
    document.getElementById('hud-n').textContent = String(idx + 1);
    if (document.body.classList.contains('overview')) slides[idx].scrollIntoView({block: 'nearest'});
    if (location.hash !== '#' + (idx + 1)) history.replaceState(null, '', '#' + (idx + 1));
  }
  function toggleOverview(){ document.body.classList.toggle('overview'); fit(); show(idx); }

  document.addEventListener('keydown', function(e){
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    switch (e.key) {
      case 'ArrowRight': case 'PageDown': case ' ': case 'Enter': show(idx + 1); e.preventDefault(); break;
      case 'ArrowLeft': case 'PageUp': case 'Backspace': show(idx - 1); e.preventDefault(); break;
      case 'Home': show(0); e.preventDefault(); break;
      case 'End':  show(slides.length - 1); e.preventDefault(); break;
      case 'o': case 'O': toggleOverview(); e.preventDefault(); break;
      case 'f': case 'F':
        if (document.fullscreenElement) document.exitFullscreen();
        else document.documentElement.requestFullscreen();
        e.preventDefault(); break;
      case 'Escape':
        if (document.body.classList.contains('overview')) { toggleOverview(); e.preventDefault(); }
        break;
    }
  });
  deck.addEventListener('click', function(e){
    if (!document.body.classList.contains('overview')) return;
    var s = e.target.closest('.slide');
    if (s) { toggleOverview(); show(slides.indexOf(s)); }
  });
  window.addEventListener('resize', fit);
  window.addEventListener('hashchange', function(){
    var n = parseInt(location.hash.slice(1), 10);
    if (!isNaN(n)) show(n - 1);
  });

  var start = parseInt(location.hash.slice(1), 10);
  fit();
  show(isNaN(start) ? 0 : start - 1);
  setTimeout(function(){ document.getElementById('help').classList.add('faded'); }, 6000);

  // ---- layout export for the PPTX build (?export) -----------------------------
  if (/(\?|&)export\b/.test(location.search)) {
    var ex = document.createElement('script');
    ex.src = '../tools/export_layout.js';
    document.body.appendChild(ex);
  }

  // ---- overflow audit (?audit) ------------------------------------------------
  if (/(\?|&)audit\b/.test(location.search)) {
    setTimeout(function(){
      var rows = [];
      slides.forEach(function(s, i){
        var was = s.style.display;
        s.style.display = 'block';
        var c = s.querySelector('.content');
        var over = c ? Math.round(c.scrollHeight - c.clientHeight) : 0;
        // absolutely-positioned footers inside .content: check they clear the other content
        var kids = c ? Array.prototype.slice.call(c.children) : [];
        var absK = kids.filter(function(k){ return k.classList.contains('abs') && k.style.bottom; });
        var flow = kids.filter(function(k){ return getComputedStyle(k).position !== 'absolute'; });
        var clash = 0;
        absK.forEach(function(a){
          var at = a.getBoundingClientRect().top;
          flow.forEach(function(k){ clash = Math.max(clash, Math.round(k.getBoundingClientRect().bottom - at)); });
        });
        s.style.display = was;
        rows.push({n: i + 1, t: s.dataset.title || 'Cover', over: over, clash: clash});
      });
      var bad = rows.filter(function(r){ return r.over > 1 || r.clash > 0; });
      var box = document.createElement('pre');
      box.id = 'audit';
      box.style.cssText = 'position:fixed;inset:0;z-index:99;margin:0;padding:24px;' +
        'background:#fff;color:#111;font:13px/1.55 Consolas,monospace;overflow:auto';
      box.textContent = 'OVERFLOW AUDIT  —  ' + bad.length + ' / ' + rows.length + ' slides flagged\n\n' +
        rows.map(function(r){
          return ((r.over > 1 || r.clash > 0) ? '  BAD  ' : '   ok  ') + String(r.n).padStart(3) +
                 '  over ' + String(r.over).padStart(4) + '  clash ' + String(r.clash).padStart(4) + '   ' + r.t;
        }).join('\n');
      document.body.appendChild(box);
    }, 2500);
  }
})();
</script>
</body>
</html>
